set-variable.value:
@{
    try {
      if (!context.Variables.ContainsKey("byokCallerAuthenticated") || !(bool)context.Variables["byokCallerAuthenticated"]
          || !context.Variables.ContainsKey("callerPrincipalKey")) { return ""; }
      var principal = (string)context.Variables["callerPrincipalKey"];
      if (string.IsNullOrWhiteSpace(principal)) { return ""; }
      var keys = new[] { "{{caller-response-owner-key}}", "{{caller-response-owner-key-previous}}" };
      var markers = new System.Collections.Generic.List<string>();
      for (var keyIndex = 0; keyIndex < keys.Length; keyIndex++) {
        if (keyIndex == 1 && keys[keyIndex] == "__none__") { continue; }
        if (!System.Text.RegularExpressions.Regex.IsMatch(keys[keyIndex], @"\A[A-Za-z0-9+/]{43}=\z")) { return ""; }
        var key = Convert.FromBase64String(keys[keyIndex]);
        if (key.Length != 32 || Convert.ToBase64String(key) != keys[keyIndex]) { return ""; }
        using (var hmac = new System.Security.Cryptography.HMACSHA256(key)) {
          var input = System.Text.Encoding.UTF8.GetBytes("byok-response-owner:v1:" + principal);
          markers.Add("v1." + BitConverter.ToString(hmac.ComputeHash(input)).Replace("-", "").ToLowerInvariant());
        }
      }
      return string.Join(",", markers);
    } catch { return ""; }
  }
